import React from "react";
import { FaSearch, FaUser, FaShoppingBag, FaMapMarkerAlt, FaPhone } from "react-icons/fa";
import "./Navbar.scss";
import insideLogo from "../../assets/inside.png";


const Navbar = () => {
  return (
    <nav className="navbar">
      {/* Barra superior */}
      <div className="navbar-top">
        <span>FRETE GRÁTIS*</span> | <span>DEVOLUÇÃO AUTOMÁTICA</span> | <span>TROCA GRÁTIS* EM LOJA</span> | <span>PARCELAMENTO ATÉ <strong>10X SEM JUROS*</strong></span> | <span>TELEATENDIMENTO: (21) 2503-6897</span>
      </div>

      {/* Navbar principal */}
      <div className="navbar-main">
        {/* Ícones à esquerda */}
        <div className="navbar-left">
          <FaMapMarkerAlt className="icon" />
          <FaPhone className="icon" />
        </div>

        {/* Logo e Links */}
        <div className="navbar-center">
          <div className="navbar-brand">ANIMALE</div>
          <ul className="navbar-links">
            <li><a href="#">NOVIDADES</a></li>
            <li><a href="#">COLEÇÃO</a></li>
            <li><a href="#">JOIAS</a></li>
            <li><a href="#">SALE</a></li>
            <img src={insideLogo} alt="Inside" className="inside-logo" />
            </ul>
        </div>

        {/* Ícones à direita */}
        <div className="navbar-right">
          <FaSearch className="icon" />
          <div className="user">
            <FaUser className="icon" />
            <span>Olá, <strong>fernanda</strong></span>
          </div>
          <div className="cart">
            <FaShoppingBag className="icon" />
            <span className="cart-count">1</span>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
